//! Generated files that are committed: one SVG per glyph (`docs/icons/svg/`) and the
//! catalog page (`docs/icons/catalog.md`). The test fails when they are out of date;
//! `UPDATE_SNAPSHOTS=1 cargo test -p archipel-icons` rewrites them.

use archipel_icons::{Category, Glyph, Language, Tones};
use std::fs;
use std::path::Path;

const DOCS: &str = "../../docs/icons";

fn update() -> bool {
    std::env::var_os("UPDATE_SNAPSHOTS").is_some()
}

/// Writes `content` to `path` when updating, else checks it is current.
fn check(path: &Path, content: &str, stale: &mut Vec<String>) {
    if update() {
        fs::create_dir_all(path.parent().expect("parent")).expect("create dir");
        fs::write(path, content).expect("write generated file");
    } else if fs::read_to_string(path).ok().as_deref() != Some(content) {
        stale.push(path.display().to_string());
    }
}

#[test]
fn svg_files_are_current() {
    let dir = Path::new(DOCS).join("svg");
    let tones = Tones {
        ink: 0,
        ..Tones::dark()
    };
    let mut stale = Vec::new();
    for glyph in Glyph::ALL {
        let svg = glyph.to_svg(16.0, &tones) + "\n";
        check(&dir.join(format!("{}.svg", glyph.name())), &svg, &mut stale);
    }
    for language in Language::ALL {
        let svg = language.to_svg(16.0) + "\n";
        check(
            &dir.join(format!("lang-{}.svg", language.slug())),
            &svg,
            &mut stale,
        );
    }
    // No files for glyphs or languages that were removed or renamed.
    for entry in fs::read_dir(&dir).expect("svg dir").flatten() {
        let name = entry.file_name().to_string_lossy().into_owned();
        let known =
            name.strip_suffix(".svg")
                .is_some_and(|stem| match stem.strip_prefix("lang-") {
                    Some(slug) => Language::ALL.iter().any(|language| language.slug() == slug),
                    None => Glyph::from_name(stem).is_some(),
                });
        if !known {
            if update() {
                fs::remove_file(entry.path()).expect("remove stale svg");
            } else {
                stale.push(format!("{name} (no such glyph or language)"));
            }
        }
    }
    assert!(
        stale.is_empty(),
        "out of date, run UPDATE_SNAPSHOTS=1 cargo test -p archipel-icons:\n{}",
        stale.join("\n")
    );
}

#[test]
fn catalog_page_is_current() {
    let mut page = String::from(
        "# Icon catalog\n\n\
         <!-- Generated by `crates/archipel-icons/tests/generated.rs`; do not edit. -->\n\n",
    );
    page += &format!(
        "{} glyphs in {} categories. Every glyph is also an SVG in [`svg/`](svg/) \
         (`currentColor`, 16×16 viewBox). In Rust: `archipel_icons::Glyph::Name`, re-exported \
         as `archipel_kit::Glyph`.\n\n",
        Glyph::ALL.len(),
        Category::ALL.len()
    );
    for category in Category::ALL {
        page += &format!("- [{}](#{})\n", category.label(), anchor(category.label()));
    }
    for category in Category::ALL {
        let slug = slug(category.label());
        page += &format!(
            "\n## {label}\n\n<picture>\n  <source media=\"(prefers-color-scheme: dark)\" srcset=\"img/{slug}.dark.png\">\n  \
             <img alt=\"{label} glyphs\" src=\"img/{slug}.light.png\" width=\"640\">\n</picture>\n\n\
             | Glyph | Name | Keywords |\n|---|---|---|\n",
            label = category.label(),
        );
        for glyph in category.glyphs() {
            page += &format!(
                "| `Glyph::{:?}` | [`{}`](svg/{}.svg) | {} |\n",
                glyph,
                glyph.name(),
                glyph.name(),
                glyph.keywords().join(", ")
            );
        }
    }
    let mut stale = Vec::new();
    check(&Path::new(DOCS).join("catalog.md"), &page, &mut stale);
    assert!(
        stale.is_empty(),
        "catalog.md is out of date, run UPDATE_SNAPSHOTS=1 cargo test -p archipel-icons"
    );
}

#[test]
fn languages_page_is_current() {
    let mut page = String::from(
        "# Language icons\n\n\
         <!-- Generated by `crates/archipel-icons/tests/generated.rs`; do not edit. -->\n\n",
    );
    page += &format!(
        "{} languages and file formats. Each icon is a tile in the language's color \
         (from [GitHub Linguist](https://github.com/github-linguist/linguist), MIT) with a \
         one- or two-letter label in the icon font. `Language::from_file_name` picks one by \
         file name, then by the longest extension. SVGs: `svg/lang-<slug>.svg`.\n\n\
         <picture>\n  <source media=\"(prefers-color-scheme: dark)\" srcset=\"img/languages.dark.png\">\n  \
         <img alt=\"All language icons with their names\" src=\"img/languages.light.png\" width=\"656\">\n</picture>\n\n\
         At actual size (16 px, 1×):\n\n\
         <picture>\n  <source media=\"(prefers-color-scheme: dark)\" srcset=\"img/languages-actual-size.dark.png\">\n  \
         <img alt=\"All language icons at 16 pixels\" src=\"img/languages-actual-size.light.png\" width=\"488\">\n</picture>\n\n\
         | Language | Label | Color | Extensions | File names |\n|---|---|---|---|---|\n",
        Language::ALL.len()
    );
    for language in Language::ALL {
        let list = |items: &[&str]| {
            items
                .iter()
                .map(|i| format!("`{i}`"))
                .collect::<Vec<_>>()
                .join(" ")
        };
        page += &format!(
            "| [{}](svg/lang-{}.svg) | `{}` | `#{:06X}` | {} | {} |\n",
            language.name().replace('|', "\\|"),
            language.slug(),
            language.label(),
            language.color(),
            list(
                &language
                    .extensions()
                    .iter()
                    .map(|e| e.replace('|', "\\|"))
                    .map(|e| format!(".{e}"))
                    .collect::<Vec<_>>()
                    .iter()
                    .map(String::as_str)
                    .collect::<Vec<_>>()
            ),
            list(language.file_names()),
        );
    }
    let mut stale = Vec::new();
    check(&Path::new(DOCS).join("languages.md"), &page, &mut stale);
    assert!(
        stale.is_empty(),
        "languages.md is out of date, run UPDATE_SNAPSHOTS=1 cargo test -p archipel-icons"
    );
}

fn slug(label: &str) -> String {
    label
        .to_lowercase()
        .replace([' ', '&'], "-")
        .replace("--", "-")
        .replace("--", "-")
}

fn anchor(label: &str) -> String {
    label
        .to_lowercase()
        .chars()
        .filter(|c| c.is_alphanumeric() || *c == ' ' || *c == '-')
        .collect::<String>()
        .replace(' ', "-")
}
